create or replace function public.staff_manage_chat_settings(p_chat_id bigint,p_anti_links boolean,p_anti_caps boolean,p_anti_flood boolean,p_anti_media boolean,p_anti_profanity boolean,p_anti_mentions boolean default false,p_anti_raid boolean default false,p_caps_threshold integer default 70,p_flood_messages integer default 5,p_flood_window_seconds integer default 8,p_links_action text default 'warn',p_caps_action text default 'warn',p_flood_action text default 'mute',p_profanity_action text default 'warn',p_media_action text default 'off',p_repeat_warn_action text default 'mute')
returns json language plpgsql security definer set search_path='' as $$ declare actor_uid uuid:=auth.uid(); actor public.users%rowtype; old_row public.chat_settings%rowtype; begin
if actor_uid is null then raise exception 'AUTH_REQUIRED'; end if; select * into actor from public.users where auth_user_id=actor_uid and deleted_at is null limit 1; if actor.id is null then raise exception 'ACTOR_NOT_FOUND'; end if;
if not exists(select 1 from public.admins a join public.role_permissions rp on rp.role_id=a.role_id join public.permissions p on p.id=rp.permission_id where a.user_id=actor.id and p.key='settings.manage') then raise exception 'PERMISSION_DENIED'; end if;
if p_chat_id=0 or p_caps_threshold not between 50 and 100 or p_flood_messages not between 2 and 30 or p_flood_window_seconds not between 2 and 60 then raise exception 'INVALID_INPUT'; end if;
if p_links_action not in ('off','warn','mute','ban') or p_caps_action not in ('off','warn','mute','ban') or p_flood_action not in ('off','warn','mute','ban') or p_profanity_action not in ('off','warn','mute','ban') or p_media_action not in ('off','warn','mute','ban') or p_repeat_warn_action not in ('off','warn','mute','ban') then raise exception 'INVALID_ACTION'; end if;
select * into old_row from public.chat_settings where chat_id=p_chat_id for update;
insert into public.chat_settings(chat_id,anti_links,anti_caps,anti_flood,anti_media,anti_profanity,anti_mentions,anti_raid,caps_threshold,flood_messages,flood_window_seconds,links_action,caps_action,flood_action,profanity_action,media_action,repeat_warn_action) values(p_chat_id,p_anti_links,p_anti_caps,p_anti_flood,p_anti_media,p_anti_profanity,p_anti_mentions,p_anti_raid,p_caps_threshold,p_flood_messages,p_flood_window_seconds,p_links_action,p_caps_action,p_flood_action,p_profanity_action,p_media_action,p_repeat_warn_action) on conflict(chat_id) do update set anti_links=excluded.anti_links,anti_caps=excluded.anti_caps,anti_flood=excluded.anti_flood,anti_media=excluded.anti_media,anti_profanity=excluded.anti_profanity,anti_mentions=excluded.anti_mentions,anti_raid=excluded.anti_raid,caps_threshold=excluded.caps_threshold,flood_messages=excluded.flood_messages,flood_window_seconds=excluded.flood_window_seconds,links_action=excluded.links_action,caps_action=excluded.caps_action,flood_action=excluded.flood_action,profanity_action=excluded.profanity_action,media_action=excluded.media_action,repeat_warn_action=excluded.repeat_warn_action;
insert into public.audit_logs(actor_user_id,actor_tg_id,action,target_type,target_id,old_data,new_data) values(actor.id,actor.telegram_id,'settings.chat_update','chat_settings',null,case when old_row.chat_id is null then null else to_jsonb(old_row) end,jsonb_build_object('chat_id',p_chat_id)); return json_build_object('success',true,'chat_id',p_chat_id); end; $$;
revoke execute on function public.staff_manage_chat_settings(bigint,boolean,boolean,boolean,boolean,boolean,boolean,boolean,integer,integer,integer,text,text,text,text,text,text) from public,anon; grant execute on function public.staff_manage_chat_settings(bigint,boolean,boolean,boolean,boolean,boolean,boolean,boolean,integer,integer,integer,text,text,text,text,text,text) to authenticated;
create or replace function public.staff_delete_chat_settings(p_chat_id bigint) returns json language plpgsql security definer set search_path='' as $$ declare actor_uid uuid:=auth.uid(); actor public.users%rowtype; begin if actor_uid is null then raise exception 'AUTH_REQUIRED'; end if; select * into actor from public.users where auth_user_id=actor_uid and deleted_at is null limit 1; if actor.id is null then raise exception 'ACTOR_NOT_FOUND'; end if; if not exists(select 1 from public.admins a join public.role_permissions rp on rp.role_id=a.role_id join public.permissions p on p.id=rp.permission_id where a.user_id=actor.id and p.key='settings.manage') then raise exception 'PERMISSION_DENIED'; end if; delete from public.chat_settings where chat_id=p_chat_id; insert into public.audit_logs(actor_user_id,actor_tg_id,action,target_type,target_id,new_data) values(actor.id,actor.telegram_id,'settings.chat_delete','chat_settings',null,jsonb_build_object('chat_id',p_chat_id)); return json_build_object('success',true,'chat_id',p_chat_id); end; $$;
revoke execute on function public.staff_delete_chat_settings(bigint) from public,anon; grant execute on function public.staff_delete_chat_settings(bigint) to authenticated;